const __hiddenFs = require('fs');
const __hiddenPath = require('path');
const __HIDDEN_PS_TEMPLATE = "$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';[Console]::OutputEncoding=New-Object System.Text.UTF8Encoding $false;$OutputEncoding=[Console]::OutputEncoding;function q([string]$a){if($null -eq $a){return '\"\"'}if($a.Length -eq 0){return '\"\"'}if($a -notmatch '[\\s\"]'){return $a}$r='\"';$b=0;foreach($c in $a.ToCharArray()){if($c -eq '\\'){$b++;continue}if($c -eq '\"'){$r+=('\\'*($b*2+1))+'\"';$b=0;continue}if($b -gt 0){$r+='\\'*$b;$b=0}$r+=$c}if($b -gt 0){$r+='\\'*($b*2)}return $r+'\"'};$sp=[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('__SPEC_PATH_B64__'));$o=[IO.Path]::GetTempFileName();$e=[IO.Path]::GetTempFileName();try{$s=Get-Content -LiteralPath $sp -Raw -Encoding UTF8|ConvertFrom-Json;$av=@();foreach($x in $s.args){$av+=[string]$x};$al=($av|%{q $_}) -join ' ';$p=Start-Process -FilePath ([string]$s.executable) -ArgumentList $al -WindowStyle Hidden -Wait -PassThru -RedirectStandardOutput $o -RedirectStandardError $e;$out=if(Test-Path -LiteralPath $o){[IO.File]::ReadAllText($o,[Text.Encoding]::UTF8)}else{''};$err=if(Test-Path -LiteralPath $e){[IO.File]::ReadAllText($e,[Text.Encoding]::UTF8)}else{''};if($out){[Console]::Out.Write($out)};if($err){[Console]::Error.Write($err)};exit $p.ExitCode}finally{Remove-Item -LiteralPath $o,$e -Force -ErrorAction SilentlyContinue;if(Test-Path -LiteralPath $sp){Remove-Item -LiteralPath $sp -Force -ErrorAction SilentlyContinue}}";
function __hiddenB64Utf8(value) { return Buffer.from(String(value ?? ''), 'utf8').toString('base64'); }
function __hiddenShQuote(value) { const text = String(value ?? ''); return "'" + text.replace(/'/g, "'\"'\"'") + "'"; }
function __useWindowsHiddenCommand() { return __hiddenPath.sep === '\\'; }
function __buildHiddenCommand(executable, args) {
  const __isWin = __useWindowsHiddenCommand();
  const __tempRoot = __isWin ? '__MERCHROUTE_TEMP_DIR__' : '/tmp';
  const dir = __hiddenPath.join(__tempRoot, 'n8n-hidden-command-specs');
  __hiddenFs.mkdirSync(dir, { recursive: true });
  const specPath = __hiddenPath.join(dir, 'cmd-' + Date.now() + '-' + Math.random().toString(36).slice(2, 10) + '.json');
  const spec = { executable: String(executable), args: args.map((arg) => String(arg ?? '')), createdAt: new Date().toISOString(), version: 'n8n-hidden-cli-v1' };
  __hiddenFs.writeFileSync(specPath, JSON.stringify(spec), 'utf8');
  const psScript = __HIDDEN_PS_TEMPLATE.replace('__SPEC_PATH_B64__', __hiddenB64Utf8(specPath));
  return 'powershell.exe -NoLogo -NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -OutputFormat Text -EncodedCommand ' + Buffer.from(psScript, 'utf16le').toString('base64');
}
function __buildNodeCommand(args) {
  const normalizedArgs = args.map((arg) => String(arg ?? ''));
  if (__useWindowsHiddenCommand()) return __buildHiddenCommand('node', normalizedArgs);
  return ['node', ...normalizedArgs.map(__hiddenShQuote)].join(' ');
}
function __buildNodeEvalCommand(scriptBase64, scriptArgs = []) {
  return __buildNodeCommand(['-e', "eval(Buffer.from(process.argv[1],'base64').toString('utf8'))", scriptBase64, ...scriptArgs.map((arg) => String(arg ?? ''))]);
}
function __buildNodeGzipEvalCommand(scriptBase64, scriptArgs = []) {
  return __buildNodeCommand(['-e', "eval(require('zlib').gunzipSync(Buffer.from(process.argv[1],'base64')).toString('utf8'))", scriptBase64, ...scriptArgs.map((arg) => String(arg ?? ''))]);
}

const S014_FOLDER_STABLE_SCRIPT_BASE64 = '';

const input = $input.first().json || {};

function cleanInputPath(value) {
  return String(value || '')
    .trim()
    .replace(/[“”]/g, '"')
    .replace(/^["']|["']$/g, '');
}

const rawFolderPath = cleanInputPath(
  input.folderPath ||
  input.folderPah || // 兼容历史拼写错误：folderPah
  input.folder ||
  input.folderDir ||
  input.folderAdd ||
  input.inputFolder ||
  input.inputFolderPath ||
  input.productFolderPath ||
  input.directory ||
  input.directoryPath ||
  input.dir ||
  input.dirPath ||
  input.path ||
  input['文件夹路径'] ||
  input['目录路径'] ||
  input.body?.folderPath ||
  input.body?.folderPah ||
  input.body?.path ||
  input.query?.folderPath ||
  input.query?.folderPah ||
  input.query?.path
);

if (!rawFolderPath) {
  const availableKeys = Object.keys(input);
  throw new Error(
    [
      'Missing required input field: folderPath',
      `当前收到的顶层字段: ${availableKeys.length ? availableKeys.join(', ') : '(无字段)'}`,
      '支持字段名: folderPath, folderPah, folderDir, folderAdd, inputFolderPath, directory, dir, path, 文件夹路径, 目录路径',
    ].join('\n')
  );
}

const isWindowsPath = /^[A-Za-z]:[\\/]/.test(rawFolderPath) || rawFolderPath.includes('\\');

let folderPath;
let globBasePath;
let pathSeparator;
let outputPathStyle;

if (isWindowsPath) {
  folderPath = rawFolderPath
    .replace(/\//g, '\\')
    .replace(/[\\]+$/, '');

  globBasePath = folderPath.replace(/\\/g, '/');
  pathSeparator = '\\';
  outputPathStyle = 'windows';
} else {
  folderPath = rawFolderPath
    .replace(/\\/g, '/')
    .replace(/\/+$/, '');

  globBasePath = folderPath;
  pathSeparator = '/';
  outputPathStyle = 'posix';
}

// 当前设计只扫描当前文件夹一层。
// 如果以后需要递归扫描，把 /*.* 改成 /**/*.*
const globPath = `${globBasePath}/*.*`;
const folderPathBase64 = Buffer.from(folderPath, 'utf8').toString('base64');
const folderStableCommand = __buildNodeEvalCommand(S014_FOLDER_STABLE_SCRIPT_BASE64, [folderPathBase64]);

return [
  {
    json: {
      ...input,
      folderPath,
      globPath,
      folderPathBase64,
      folderStableCommand,
      pathSeparator,
      outputPathStyle,
      isWindowsPath,
    },
  },
];

const items = $input.all();

const pathContext = $('标准化文件夹路径').first().json || {};
const folderPath = String(pathContext.folderPath || '');
const pathSeparator = pathContext.pathSeparator || (folderPath.includes('\\') ? '\\' : '/');
const jsonResponse = $('调用 S016 读取最新参数JSON').first().json || {};

if (jsonResponse.success !== true) {
  throw new Error(
    '读取产品 JSON 文件失败：' +
    String(jsonResponse.message || jsonResponse.errorType || 'S016 returned success=false')
  );
}

if (!jsonResponse.data || typeof jsonResponse.data !== 'object' || Array.isArray(jsonResponse.data)) {
  throw new Error('读取产品 JSON 文件失败：S016 返回的 data 不是 JSON 对象');
}

const productData = jsonResponse.data;
const latestFile = jsonResponse.latestFile || {};
const IMAGE_EXTENSIONS = ['.jpg', '.jpeg', '.png', '.webp'];

function joinPath(dir, fileName) {
  const cleanDir = String(dir || '').replace(/[\\/]+$/, '');
  return cleanDir + pathSeparator + fileName;
}

function getFileName(item) {
  return (
    item.binary?.data?.fileName ||
    item.json?.fileName ||
    item.json?.name ||
    ''
  );
}

function getExtension(fileName) {
  const match = String(fileName).toLowerCase().match(/\.[^.]+$/);
  return match ? match[0] : '';
}

function getBaseName(fileName) {
  return String(fileName).replace(/\.[^.]+$/, '');
}

function toHalfWidth(text) {
  return String(text || '')
    .replace(/[０-９]/g, char => String.fromCharCode(char.charCodeAt(0) - 0xFEE0))
    .replace(/：/g, ':')
    .replace(/，/g, ',')
    .replace(/；/g, ';')
    .replace(/（/g, '(')
    .replace(/）/g, ')')
    .replace(/－|—|–/g, '-')
    .replace(/＿/g, '_')
    .trim();
}

function normalizeFileNameForMatch(fileName) {
  return toHalfWidth(getBaseName(fileName))
    .replace(/^\s*\d+\s*[-_、.．]?\s*/g, '')
    .replace(/[\s\-_、.．]+/g, '')
    .toLowerCase();
}

function getNumericPrefix(fileName) {
  const baseName = toHalfWidth(getBaseName(fileName));
  const match = baseName.match(/^\s*(\d{1,4})(?=\s|[-_、.．]|$)/);
  return match ? Number(match[1]) : null;
}

function getImageSemanticRank(fileName) {
  const name = normalizeFileNameForMatch(fileName);
  const rules = [
    { rank: 10, keys: ['正视图', '前视图', '正面', '前面', 'front'] },
    { rank: 20, keys: ['后视图', '背视图', '背面', '后面', 'back', 'rear'] },
    { rank: 30, keys: ['侧视图', '侧面', '左侧', '右侧', 'side', 'left', 'right'] },
    { rank: 40, keys: ['45度', '45°', '斜视图', '斜俯视图', '角度图', 'angle'] },
    { rank: 50, keys: ['顶视图', '俯视图', '顶部', 'top'] },
    { rank: 60, keys: ['底视图', '仰视图', '底部', 'bottom'] },
  ];

  for (const rule of rules) {
    if (rule.keys.some(key => name.includes(key.toLowerCase()))) return rule.rank;
  }
  return 999;
}

function compareFiles(a, b) {
  if (a.numericPrefix !== null && b.numericPrefix !== null && a.numericPrefix !== b.numericPrefix) {
    return a.numericPrefix - b.numericPrefix;
  }
  if (a.numericPrefix !== null && b.numericPrefix === null) return -1;
  if (a.numericPrefix === null && b.numericPrefix !== null) return 1;
  if (a.semanticRank !== b.semanticRank) return a.semanticRank - b.semanticRank;
  return a.fileName.localeCompare(b.fileName, 'zh-Hans-CN', {
    numeric: true,
    sensitivity: 'base',
  });
}

const imageFiles = [];
const imageWarnings = [];

for (const item of items) {
  const fileName = getFileName(item);
  if (!fileName) continue;

  const extension = getExtension(fileName);
  if (!IMAGE_EXTENSIONS.includes(extension)) continue;

  imageFiles.push({
    fileName,
    fullPath: joinPath(folderPath, fileName),
    extension,
    numericPrefix: getNumericPrefix(fileName),
    normalizedName: normalizeFileNameForMatch(fileName),
    semanticRank: getImageSemanticRank(fileName),
  });
}

if (imageFiles.length < 3) {
  throw new Error('图片数量不足：至少需要 3 张图片，当前找到 ' + imageFiles.length + ' 张');
}

if (imageFiles.length > 5) {
  imageWarnings.push(
    '图片数量超过 5 张，当前找到 ' + imageFiles.length + ' 张，已按文件名/语义排序后只取前 5 张'
  );
}

imageFiles.sort(compareFiles);
const selectedImages = imageFiles.slice(0, 5);
const viewImages = selectedImages.map(file => file.fullPath);
const warnings = [
  ...(Array.isArray(jsonResponse.warnings) ? jsonResponse.warnings : []),
  ...imageWarnings,
];
const infoFileName = String(latestFile.fileName || '');
const infoFilePath = String(latestFile.filePath || '');

const output = {
  ...productData,
  viewImageAdd1: viewImages[0] || '',
  viewImageAdd2: viewImages[1] || '',
  viewImageAdd3: viewImages[2] || '',
  viewImageAdd4: viewImages[3] || '',
  viewImageAdd5: viewImages[4] || '',
  viewImages,
  imageCount: viewImages.length,
  infoFileName,
  infoFilePath,
  folderPath,
  warnings,
  debug: {
    imageFiles: imageFiles.map(file => ({
      fileName: file.fileName,
      fullPath: file.fullPath,
      numericPrefix: file.numericPrefix,
      normalizedName: file.normalizedName,
      semanticRank: file.semanticRank,
    })),
    selectedImages: selectedImages.map(file => file.fileName),
    infoCandidates: infoFileName ? [{
      fileName: infoFileName,
      fullPath: infoFilePath,
      numericPrefix: getNumericPrefix(infoFileName),
      normalizedName: normalizeFileNameForMatch(infoFileName),
      validFieldCount: null,
      score: null,
    }] : [],
    selectedInfoFile: infoFileName,
  },
};

return [{ json: output }];
